// ---- pointer targets: allocation and resolution (docs/SPEC-TABLES.md §2) ----
//
// A reference resolves differently in the two forms, and the CONTEXT says
// which: in the arena it is an offset; in a region it is a self-relative
// delta, so the const deref below is one add and needs no base pointer.

// LogEntry is a pointer target.
inline const LogEntry * LogEntryAt( const TableRef & ref ) // the const form's hot path: one add, no base
{
    return ref.value != 0 ? (const LogEntry *) ( (const uint8_t *) &ref + ref.value ) : NULL;
}
inline LogEntry * LogEntryAt( TableRef & ref )
{
    return ref.value != 0 ? (LogEntry *) ( (uint8_t *) &ref + ref.value ) : NULL;
}
inline const LogEntry * LogEntryAt( const TableRegionCtx &, const TableRef & ref ) { return LogEntryAt( ref ); }
inline const LogEntry * LogEntryAt( const TableArenaCtx & ctx, const TableRef & ref )
{
    return ref.value != 0 ? (const LogEntry *) TableArenaAt( *ctx.arena, (uint32_t) ref.value ) : NULL;
}
// while the builder is mutable, resolve against the arena itself
inline LogEntry * LogEntryAt( TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (LogEntry *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
inline const LogEntry * LogEntryAt( const TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (const LogEntry *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
// allocate one LogEntry in the arena; the slot holds the arena offset
inline LogEntry * LogEntryEmplace( TableWorker & worker, TableRef & slot )
{
    TableSlot<LogEntry> allocated = worker.Alloc<LogEntry>();
    slot = allocated.ref;
    return allocated.ptr;
}

