// SaveWireExtent: the extent Save's lists and maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool SaveWireExtent( const uint8_t * body, int64_t length, int64_t & at, const TableIdTable * ids, TableRefuseReason & reason )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch, ids );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) ) { return true; }
        if ( field_ref == 0 ) { return true; }
        if ( ids == NULL || field_ref > (uint64_t) ids->count ) { return true; }
        const uint64_t field_id = ids->at( field_ref );
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0xd24733aa574d4b09ull && field_kind == 14 ) // placements: an unbounded array
        {
            uint64_t list_len = 0;
            if ( !r.getleb( list_len ) || !r.room( list_len ) ) { return true; }
            const uint8_t * list_body = r.buffer + r.offset;
            r.offset += (int64_t) list_len;
            if ( !TableListWireExtent( list_body, (int64_t) list_len, at, (int64_t) sizeof( Placement ), (int64_t) alignof( Placement ), 13, 2, NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x125073191daf5431ull && field_kind == 14 ) // log: an unbounded array
        {
            uint64_t list_len = 0;
            if ( !r.getleb( list_len ) || !r.room( list_len ) ) { return true; }
            const uint8_t * list_body = r.buffer + r.offset;
            r.offset += (int64_t) list_len;
            if ( !TableListWireExtent( list_body, (int64_t) list_len, at, (int64_t) sizeof( TableRef ), (int64_t) alignof( TableRef ), 17, 1, NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x01986b0b27400fb2ull && field_kind == 14 ) // scores: an unbounded array
        {
            uint64_t list_len = 0;
            if ( !r.getleb( list_len ) || !r.room( list_len ) ) { return true; }
            const uint8_t * list_body = r.buffer + r.offset;
            r.offset += (int64_t) list_len;
            if ( !TableListWireExtent( list_body, (int64_t) list_len, at, (int64_t) sizeof( int32_t ), (int64_t) alignof( int32_t ), 4, 4, NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

// SaveExtentAt: the node extent Save's lists and maps take, PRE-ORDER, advancing
// the running offset exactly as SaveExtentPack advances it (§2.8, §2.9).
template <typename Ctx>
inline bool SaveExtentAt( const Ctx & ctx, const Save & value, int64_t & at )
{
    {
        TableListCursor<Placement> cursor = TableListElements( ctx, value.placements );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( Placement ) - 1 ) & ~( (int64_t) alignof( Placement ) - 1 );
        at += (int64_t) cursor.count * (int64_t) sizeof( Placement ); // the whole array FIRST
    }
    {
        TableListCursor<TableRef> cursor = TableListElements( ctx, value.log );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( TableRef ) - 1 ) & ~( (int64_t) alignof( TableRef ) - 1 );
        at += (int64_t) cursor.count * (int64_t) sizeof( TableRef ); // the whole array FIRST
    }
    {
        TableListCursor<int32_t> cursor = TableListElements( ctx, value.scores );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( int32_t ) - 1 ) & ~( (int64_t) alignof( int32_t ) - 1 );
        at += (int64_t) cursor.count * (int64_t) sizeof( int32_t ); // the whole array FIRST
    }
    return true;
}

// the whole extent of one node, from a fresh offset: what a pack reserves
// for it beside the record's own storage.
template <typename Ctx>
inline int64_t SaveExtent( const Ctx & ctx, const Save & value )
{
    int64_t at = 0;
    if ( !SaveExtentAt( ctx, value, at ) ) { return -1; }
    return at;
}

// SaveExtentPack: carve Save's arrays out of the node's extent and copy the
// entries in ASCENDING key order and the elements in INDEX order, PRE-ORDER,
// advancing the same running offset SaveExtentAt advances (§2.8, §2.9).
template <typename Ctx>
inline bool SaveExtentPack( const Ctx & ctx, const Save & src, Save & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableListCursor<Placement> cursor = TableListElements( ctx, src.placements );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( Placement ) - 1 ) & ~( (int64_t) alignof( Placement ) - 1 );
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( Placement );
        if ( at + bytes > capacity ) { return false; }
        Placement * placed = (Placement *) ( extent + at );
        at += bytes;
        dst.placements.count = cursor.count;
        dst.placements.padding = 0;
        dst.placements.elements.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.placements.elements ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            memcpy( (void *) ( placed + i ), (const void *) &cursor[i], sizeof( Placement ) ); // trivially copyable, by construction
        }
    }
    {
        TableListCursor<TableRef> cursor = TableListElements( ctx, src.log );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( TableRef ) - 1 ) & ~( (int64_t) alignof( TableRef ) - 1 );
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( TableRef );
        if ( at + bytes > capacity ) { return false; }
        TableRef * placed = (TableRef *) ( extent + at );
        at += bytes;
        dst.log.count = cursor.count;
        dst.log.padding = 0;
        dst.log.elements.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.log.elements ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            memcpy( (void *) ( placed + i ), (const void *) &cursor[i], sizeof( TableRef ) ); // trivially copyable, by construction
        }
    }
    {
        TableListCursor<int32_t> cursor = TableListElements( ctx, src.scores );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( int32_t ) - 1 ) & ~( (int64_t) alignof( int32_t ) - 1 );
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( int32_t );
        if ( at + bytes > capacity ) { return false; }
        int32_t * placed = (int32_t *) ( extent + at );
        at += bytes;
        dst.scores.count = cursor.count;
        dst.scores.padding = 0;
        dst.scores.elements.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.scores.elements ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            memcpy( (void *) ( placed + i ), (const void *) &cursor[i], sizeof( int32_t ) ); // trivially copyable, by construction
        }
    }
    return true;
}

