// LogEntryNumber: number everything LogEntry POINTS AT, in first-visit order —
// the fields in declaration order, a by-value edge descended in place.
// A reference to an entry whose descent is still OPEN is a data cycle,
// named here rather than recursed away (docs/SPEC-TABLES.md §3.1).
template <typename Ctx>
inline bool LogEntryNumber( const Ctx & ctx, TableNumbering & numbering, const LogEntry & value )
{
    (void) ctx; (void) numbering; (void) value; // no pointers below this node
    return true;
}

// LogEntryPackMeasure: the packed region bytes of everything LogEntry POINTS AT.
// ONE VISIT PER NODE: `seen` carries the first-visit numbering (§3.1), so a
// node two references name is measured ONCE and packed once, and a
// reference to a node whose descent is still open is a data cycle, refused.
template <typename Ctx>
inline int64_t LogEntryPackMeasure( const Ctx & ctx, TablePackMap & seen, const LogEntry & value )
{
    int64_t bytes = 0;
    (void) ctx; (void) seen; (void) value; // no pointers below this node
    return bytes;
}

// LogEntryPack: copy src into dst (already placed), then lay every pointee out
// depth-first behind it, in FIELD ORDER, by bump allocation.
//
// ONE NODE, ONE BODY (§6.2): `seen` holds every node already placed and
// where it landed, so a node's FIRST reference lays it out and every later
// reference points BACK at that one body. A region delta therefore has no
// required sign (§6.3), and sharing and a back-reference are one fact. A
// reference to a node whose descent is still OPEN is a cycle, and this
// refuses it rather than packing one.
template <typename Ctx>
inline bool LogEntryPackEdges( const Ctx & ctx, TablePackMap & seen, const LogEntry & src, LogEntry & dst, uint8_t * base, int64_t capacity, int64_t & used );

template <typename Ctx>
inline bool LogEntryPack( const Ctx & ctx, TablePackMap & seen, const LogEntry & src, LogEntry & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    memcpy( (void *) &dst, (const void *) &src, sizeof( LogEntry ) ); // trivially copyable, by construction
    int64_t at = 0;
    uint8_t * extent = (uint8_t *) &dst + TableAlignUp64( (int64_t) sizeof( LogEntry ) );
    const int64_t room = capacity - ( (int64_t) ( extent - base ) );
    if ( !LogEntryExtentPack( ctx, src, dst, extent, at, room ) ) { return false; }
    return LogEntryPackEdges( ctx, seen, src, dst, base, capacity, used );
}

template <typename Ctx>
inline bool LogEntryPackEdges( const Ctx & ctx, TablePackMap & seen, const LogEntry & src, LogEntry & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    (void) ctx; (void) seen; (void) src; (void) dst; (void) base; (void) capacity; (void) used;
    return true;
}

// SaveNumber: number everything Save POINTS AT, in first-visit order —
// the fields in declaration order, a by-value edge descended in place.
// A reference to an entry whose descent is still OPEN is a data cycle,
// named here rather than recursed away (docs/SPEC-TABLES.md §3.1).
template <typename Ctx>
inline bool SaveNumber( const Ctx & ctx, TableNumbering & numbering, const Save & value )
{
    { // log: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<TableRef> cursor_log = TableListElements( ctx, value.log );
        if ( !cursor_log.ok ) { return false; }
        for ( int32_t i = 0; i < cursor_log.count; i++ )
        {
            {
                const LogEntry * pointee = LogEntryAt( ctx, cursor_log[i] ); // log
                if ( pointee != NULL )
                {
                    bool taken = false;
                    int64_t slot = 0;
                    const TablePackEntry * entry = TablePackMapReach( numbering.seen, (const void *) pointee,
                        (int64_t) ( numbering.count + 2 ), taken, slot ); // its index, if this is its first visit
                    if ( entry == NULL ) { return false; } // the map could not grow
                    if ( !taken )
                    {
                        if ( entry->open != 0 ) { return false; } // a data cycle
                    }
                    else
                    {
                        TableNodeEntry node;
                        node.node = (const void *) pointee;
                        node.type_id = 0x5e781536ac58825full; // fnv1a64( "LogEntry" )
                        node.type_slot = 53; // its slot in the unit's vocabulary (§3.3)
                        node.measure = &TableNodeMeasureThunk<Ctx, LogEntry>;
                        node.save = &TableNodeSaveThunk<Ctx, LogEntry>;
                        node.message_measure = &TableNodeMessageMeasureThunk<Ctx, LogEntry>;
                        node.message_save = &TableNodeMessageSaveThunk<Ctx, LogEntry>;
                        if ( !TableNumberingAppend( numbering, node ) ) { return false; }
                        if ( !LogEntryNumber( ctx, numbering, *pointee ) ) { return false; }
                        TablePackMapClose( numbering.seen, (const void *) pointee, slot );
                    }
                }
            }
        }
    }
    return true;
}

// SavePackMeasure: the packed region bytes of everything Save POINTS AT.
// ONE VISIT PER NODE: `seen` carries the first-visit numbering (§3.1), so a
// node two references name is measured ONCE and packed once, and a
// reference to a node whose descent is still open is a data cycle, refused.
template <typename Ctx>
inline int64_t SavePackMeasure( const Ctx & ctx, TablePackMap & seen, const Save & value )
{
    int64_t bytes = 0;
    { // log: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<TableRef> cursor_log = TableListElements( ctx, value.log );
        if ( !cursor_log.ok ) { return -1; }
        for ( int32_t i = 0; i < cursor_log.count; i++ )
        {
            {
                const LogEntry * pointee = LogEntryAt( ctx, cursor_log[i] ); // log
                if ( pointee != NULL )
                {
                    bool taken = false;
                    int64_t slot = 0;
                    const TablePackEntry * entry = TablePackMapReach( seen, (const void *) pointee, 0, taken, slot );
                    if ( entry == NULL ) { return -1; } // the map could not grow
                    if ( !taken )
                    {
                        if ( entry->open != 0 ) { return -1; } // a data cycle
                    }
                    else
                    {
                        int64_t inner = LogEntryPackMeasure( ctx, seen, *pointee );
                        if ( inner < 0 ) { return -1; }
                        TablePackMapClose( seen, (const void *) pointee, slot );
                        bytes += TableAlignUp64( (int64_t) sizeof( LogEntry ) ) + inner;
                    }
                }
            }
        }
    }
    return bytes;
}

// SavePack: copy src into dst (already placed), then lay every pointee out
// depth-first behind it, in FIELD ORDER, by bump allocation.
//
// ONE NODE, ONE BODY (§6.2): `seen` holds every node already placed and
// where it landed, so a node's FIRST reference lays it out and every later
// reference points BACK at that one body. A region delta therefore has no
// required sign (§6.3), and sharing and a back-reference are one fact. A
// reference to a node whose descent is still OPEN is a cycle, and this
// refuses it rather than packing one.
template <typename Ctx>
inline bool SavePackEdges( const Ctx & ctx, TablePackMap & seen, const Save & src, Save & dst, uint8_t * base, int64_t capacity, int64_t & used );

template <typename Ctx>
inline bool SavePack( const Ctx & ctx, TablePackMap & seen, const Save & src, Save & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    memcpy( (void *) &dst, (const void *) &src, sizeof( Save ) ); // trivially copyable, by construction
    int64_t at = 0;
    uint8_t * extent = (uint8_t *) &dst + TableAlignUp64( (int64_t) sizeof( Save ) );
    const int64_t room = capacity - ( (int64_t) ( extent - base ) );
    if ( !SaveExtentPack( ctx, src, dst, extent, at, room ) ) { return false; }
    return SavePackEdges( ctx, seen, src, dst, base, capacity, used );
}

template <typename Ctx>
inline bool SavePackEdges( const Ctx & ctx, TablePackMap & seen, const Save & src, Save & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    { // log: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<TableRef> cursor_log = TableListElements( ctx, src.log );
        if ( !cursor_log.ok ) { return false; }
        TableRef * placed_log = (TableRef *) ( dst.log.elements.value != 0 ? ( (uint8_t *) &dst.log.elements + dst.log.elements.value ) : NULL );
        for ( int32_t i = 0; i < cursor_log.count; i++ )
        {
            {
                placed_log[i].value = 0; // log
                const LogEntry * pointee = LogEntryAt( ctx, cursor_log[i] );
                if ( pointee != NULL )
                {
                    int64_t at = TableAlignUp64( used ); // where it WOULD land, if this is its first visit
                    bool taken = false;
                    int64_t slot = 0;
                    const TablePackEntry * entry = TablePackMapReach( seen, (const void *) pointee, at, taken, slot );
                    if ( entry == NULL ) { return false; } // the map could not grow
                    if ( !taken )
                    {
                        if ( entry->open != 0 ) { return false; } // a data cycle
                        placed_log[i].value = (int64_t) ( ( base + entry->offset ) - (const uint8_t *) &placed_log[i] ); // the one body it already has
                    }
                    else
                    {
                        if ( at + (int64_t) sizeof( LogEntry ) > capacity ) { return false; }
                        used = at + TableAlignUp64( (int64_t) sizeof( LogEntry ) );
                        LogEntry * child = new ( base + at ) LogEntry; // lifetime only: the Pack below memcpy's the whole node over it
                        placed_log[i].value = (int64_t) ( ( base + at ) - (const uint8_t *) &placed_log[i] );
                        if ( !LogEntryPack( ctx, seen, *pointee, *child, base, capacity, used ) ) { return false; }
                        TablePackMapClose( seen, (const void *) pointee, slot );
                    }
                }
            }
        }
    }
    return true;
}

