// ---- the cooked form: WRITE a cook (docs/SPEC-TABLES.md §7.6) ----
//
// The bytes are `schema cook`'s, and the tool stays the reference: the two
// writers are held to one file, byte for byte, in both byte orders. A cook is
// content-addressed by (asset hash, build version), so two writers of one
// instance produce ONE artifact or the pair means nothing.

inline void PlacementCookBody( uint8_t * at, const Placement & value, TableByteOrder order );
inline void LogEntryCookBody( uint8_t * at, const LogEntry & value, TableByteOrder order );
template <typename Ctx> inline bool SaveCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Save & value, TableByteOrder order );
inline void PointCookBody( uint8_t * at, const Point & value, TableByteOrder order );
template <typename Ctx> inline bool MixedCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Mixed & value, TableByteOrder order );

inline void PlacementCookBody( uint8_t * at, const Placement & value, TableByteOrder order )
{
    { uint32_t bits = 0; memcpy( &bits, &value.x, 4 ); table_cook_put( at + 0, (uint64_t) bits, 4, order ); }
    { uint32_t bits = 0; memcpy( &bits, &value.y, 4 ); table_cook_put( at + 4, (uint64_t) bits, 4, order ); }
    table_cook_put( at + 8, (uint64_t) value.model, 4, order );
}

inline void LogEntryCookBody( uint8_t * at, const LogEntry & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.tick, 4, order );
}

template <typename Ctx> inline bool SaveCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Save & value, TableByteOrder order )
{
    (void) ctx; (void) region; // no reference resolves in this body: a list's and a map's slots are the extent writer's, and the class was decided elsewhere in the closure
    (void) value;
    table_cook_put( at + 0, 0, 8, order ); // placements: the array's delta, filled by the extent writer
    table_cook_put( at + 8, 0, 4, order ); // and its count
    table_cook_put( at + 16, 0, 8, order ); // log: the array's delta, filled by the extent writer
    table_cook_put( at + 24, 0, 4, order ); // and its count
    table_cook_put( at + 32, 0, 8, order ); // scores: the array's delta, filled by the extent writer
    table_cook_put( at + 40, 0, 4, order ); // and its count
    return true;
}

inline void PointCookBody( uint8_t * at, const Point & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.x, 4, order );
    table_cook_put( at + 4, (uint64_t) value.y, 4, order );
}

template <typename Ctx> inline bool MixedCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Mixed & value, TableByteOrder order )
{
    (void) ctx; (void) region; // no reference resolves in this body: a list's and a map's slots are the extent writer's, and the class was decided elsewhere in the closure
    (void) value;
    table_cook_put( at + 0, 0, 8, order ); // grades: the array's delta, filled by the extent writer
    table_cook_put( at + 8, 0, 4, order ); // and its count
    table_cook_put( at + 16, 0, 8, order ); // perms: the array's delta, filled by the extent writer
    table_cook_put( at + 24, 0, 4, order ); // and its count
    table_cook_put( at + 32, 0, 8, order ); // hits: the array's delta, filled by the extent writer
    table_cook_put( at + 40, 0, 4, order ); // and its count
    table_cook_put( at + 48, 0, 8, order ); // bounds: the array's delta, filled by the extent writer
    table_cook_put( at + 56, 0, 4, order ); // and its count
    return true;
}

