// PlacementCookExtent: Placement's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx> inline bool PlacementCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Placement & value, TableByteOrder order )
{
    (void) ctx; (void) region; (void) extent; (void) at; (void) record; (void) value; (void) order;
    return true; // no list or map below this record
}

// LogEntryCookExtent: LogEntry's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx> inline bool LogEntryCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const LogEntry & value, TableByteOrder order )
{
    (void) ctx; (void) region; (void) extent; (void) at; (void) record; (void) value; (void) order;
    return true; // no list or map below this record
}

// SaveCookExtent: Save's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx> inline bool SaveCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Save & value, TableByteOrder order )
{
    { // placements: an unbounded array
        TableListCursor<Placement> cursor = TableListElements( ctx, value.placements );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( Placement )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 12; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 0, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 0 ) ) : 0, 8, order );
        table_cook_put( record + 8, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            PlacementCookBody( array + i * 12, cursor[i], order );
        }
    }
    { // log: an unbounded array
        TableListCursor<TableRef> cursor = TableListElements( ctx, value.log );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( TableRef )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 8; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 16, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 16 ) ) : 0, 8, order );
        table_cook_put( record + 24, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            if ( !table_cook_ref( region, array + i * 8, (const void *) LogEntryAt( ctx, cursor[i] ), order ) ) { return false; }
        }
    }
    { // scores: an unbounded array
        TableListCursor<int32_t> cursor = TableListElements( ctx, value.scores );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( int32_t )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 4; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 32, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 32 ) ) : 0, 8, order );
        table_cook_put( record + 40, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            table_cook_put( array + i * 4, (uint64_t) cursor[i], 4, order );
        }
    }
    return true;
}

// PointCookExtent: Point's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx> inline bool PointCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Point & value, TableByteOrder order )
{
    (void) ctx; (void) region; (void) extent; (void) at; (void) record; (void) value; (void) order;
    return true; // no list or map below this record
}

// MixedCookExtent: Mixed's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx> inline bool MixedCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Mixed & value, TableByteOrder order )
{
    (void) region; // a table element's and an entry's references resolve through their own bodies
    { // grades: an unbounded array
        TableListCursor<Grade> cursor = TableListElements( ctx, value.grades );
        if ( !cursor.ok ) { return false; }
        at = ( at + 0 ) & ~(int64_t) 0; // at alignof( Grade )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 1; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 0, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 0 ) ) : 0, 8, order );
        table_cook_put( record + 8, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            table_cook_put( array + i * 1, (uint64_t) cursor[i], 1, order );
        }
    }
    { // perms: an unbounded array
        TableListCursor<Perm> cursor = TableListElements( ctx, value.perms );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( Perm )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 8; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 16, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 16 ) ) : 0, 8, order );
        table_cook_put( record + 24, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            table_cook_put( array + i * 8, (uint64_t) cursor[i], 8, order ); // a mask rides raw, in every target
        }
    }
    { // hits: an unbounded array
        TableListCursor<Hit> cursor = TableListElements( ctx, value.hits );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( Hit )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 12; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 32, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 32 ) ) : 0, 8, order );
        table_cook_put( record + 40, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            {
                table_cook_put( array + i * 12, (uint64_t) cursor[i].type, 1, order ); // the tag; None is the tag alone
                switch ( cursor[i].type )
                {
                    case HitType::Point: PointCookBody( array + i * 12 + 4, cursor[i].point, order ); break;
                    case HitType::Damage:
                    {
                        table_cook_put( array + i * 12 + 4, (uint64_t) cursor[i].damage, 4, order );
                        break;
                    }
                    default: break; // every byte outside the set arm stays zero
                }
            }
        }
    }
    { // bounds: an unbounded array
        TableListCursor<int32_t> cursor = TableListElements( ctx, value.bounds );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( int32_t )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 4; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 48, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 48 ) ) : 0, 8, order );
        table_cook_put( record + 56, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            table_cook_put( array + i * 4, (uint64_t) cursor[i], 4, order );
        }
    }
    return true;
}

// PlacementCookNode: one node, the record, then the extent its lists and maps take (§2.8, §2.9).
template <typename Ctx> inline bool PlacementCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Placement & value, TableByteOrder order )
{
    PlacementCookBody( at, value, order );
    int64_t extent_at = 0;
    return PlacementCookExtent( ctx, region, at + 16, extent_at, at, value, order );
}

// LogEntryCookNode: one node, the record, then the extent its lists and maps take (§2.8, §2.9).
template <typename Ctx> inline bool LogEntryCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const LogEntry & value, TableByteOrder order )
{
    LogEntryCookBody( at, value, order );
    int64_t extent_at = 0;
    return LogEntryCookExtent( ctx, region, at + 8, extent_at, at, value, order );
}

// SaveCookNode: one node, the record, then the extent its lists and maps take (§2.8, §2.9).
template <typename Ctx> inline bool SaveCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Save & value, TableByteOrder order )
{
    if ( !SaveCookBody( ctx, region, at, value, order ) ) { return false; }
    int64_t extent_at = 0;
    if ( !SaveCookExtent( ctx, region, at + 48, extent_at, at, value, order ) ) { return false; }
    return extent_at == SaveExtent( ctx, value ); // the extent written is the extent measured, or no header is written
}

// PointCookNode: one node, the record, then the extent its lists and maps take (§2.8, §2.9).
template <typename Ctx> inline bool PointCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Point & value, TableByteOrder order )
{
    PointCookBody( at, value, order );
    int64_t extent_at = 0;
    return PointCookExtent( ctx, region, at + 8, extent_at, at, value, order );
}

// MixedCookNode: one node, the record, then the extent its lists and maps take (§2.8, §2.9).
template <typename Ctx> inline bool MixedCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Mixed & value, TableByteOrder order )
{
    if ( !MixedCookBody( ctx, region, at, value, order ) ) { return false; }
    int64_t extent_at = 0;
    if ( !MixedCookExtent( ctx, region, at + 64, extent_at, at, value, order ) ) { return false; }
    return extent_at == MixedExtent( ctx, value ); // the extent written is the extent measured, or no header is written
}

// PlacementCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// Placement IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t PlacementCookMeasure( const Placement & value )
{
    (void) value;
    return 96; // 64 header + 16 data + 16 attribution
}

// PlacementCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract PlacementMeasure/PlacementSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool PlacementCook( const Placement & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) PlacementCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 16, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    PlacementCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 80, 0, 8, order );
    table_cook_put( raw + 88, 0x41f721f1b93aea80ull, 8, order );
    return true;
}

// LogEntryCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// LogEntry IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t LogEntryCookMeasure( const LogEntry & value )
{
    (void) value;
    return 88; // 64 header + 8 data + 16 attribution
}

// LogEntryCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract LogEntryMeasure/LogEntrySave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool LogEntryCook( const LogEntry & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) LogEntryCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 8, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    LogEntryCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 72, 0, 8, order );
    table_cook_put( raw + 80, 0x5e781536ac58825full, 8, order );
    return true;
}

// SaveCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
// A NODE'S SIZE DEPENDS ON ITS VALUE where a list or a map rides in its extent
// (docs/SPEC-TABLES.md §2.8), so the layout takes the resolution context
// the numbering walked and reads the same arrays that walk read.
template <typename Ctx>
inline bool SaveCookLayout( const Ctx & ctx, const Save & root, const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    const int64_t root_extent = SaveExtent( ctx, root );
    if ( root_extent < 0 ) { return false; }
    int64_t offset = 48 + root_extent; // the root at zero, its extent behind it
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            case 0x5e781536ac58825full: size = 4; node_align = 4; break; // LogEntry
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// SaveCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t SaveCookMeasureFrom( const Ctx & ctx, const Save & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( SaveNumberFrom( ctx, numbering, root ) && SaveCookLayout( ctx, root, numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// SaveCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool SaveCookFrom( const Ctx & ctx, const Save & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = SaveNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && SaveCookLayout( ctx, root, numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = SaveCookNode( ctx, region, region.base, root, order );
            for ( int64_t k = 0; ok && k < numbering.count; k++ )
            {
                uint8_t * at = region.base + region.offsets[k + 1];
                const void * node = numbering.entries[k].node;
                switch ( numbering.entries[k].type_id )
                {
                    case 0x5e781536ac58825full: ok = LogEntryCookNode( ctx, region, at, *(const LogEntry *) node, order ); break; // LogEntry
                    default: ok = false; break;
                }
            }
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0x33f85f24c0f5f008ull, 8, order ); // the root: fnv1a64( "Save" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// SaveCookMeasure / SaveCook over a REGION root — a locked builder's AsConst, a
// region SaveLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t SaveCookMeasure( const Save * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return SaveCookMeasureFrom( ctx, *root, allocator );
}

inline bool SaveCook( const Save * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return SaveCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t SaveCookMeasure( const SaveBuilder & builder )
{
    if ( builder.region != NULL ) { return SaveCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return SaveCookMeasureFrom( ctx, *(const Save *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool SaveCook( const SaveBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return SaveCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return SaveCookFrom( ctx, *(const Save *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// PointCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// Point IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t PointCookMeasure( const Point & value )
{
    (void) value;
    return 88; // 64 header + 8 data + 16 attribution
}

// PointCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract PointMeasure/PointSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool PointCook( const Point & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) PointCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 8, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    PointCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 72, 0, 8, order );
    table_cook_put( raw + 80, 0x8a439296ced9ed11ull, 8, order );
    return true;
}

// MixedCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
// A NODE'S SIZE DEPENDS ON ITS VALUE where a list or a map rides in its extent
// (docs/SPEC-TABLES.md §2.8), so the layout takes the resolution context
// the numbering walked and reads the same arrays that walk read.
template <typename Ctx>
inline bool MixedCookLayout( const Ctx & ctx, const Mixed & root, const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    const int64_t root_extent = MixedExtent( ctx, root );
    if ( root_extent < 0 ) { return false; }
    int64_t offset = 64 + root_extent; // the root at zero, its extent behind it
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// MixedCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t MixedCookMeasureFrom( const Ctx & ctx, const Mixed & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( MixedNumberFrom( ctx, numbering, root ) && MixedCookLayout( ctx, root, numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// MixedCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool MixedCookFrom( const Ctx & ctx, const Mixed & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = MixedNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && MixedCookLayout( ctx, root, numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = MixedCookNode( ctx, region, region.base, root, order );
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0xbb86c6c96f598bb8ull, 8, order ); // the root: fnv1a64( "Mixed" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// MixedCookMeasure / MixedCook over a REGION root — a locked builder's AsConst, a
// region MixedLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t MixedCookMeasure( const Mixed * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return MixedCookMeasureFrom( ctx, *root, allocator );
}

inline bool MixedCook( const Mixed * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return MixedCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t MixedCookMeasure( const MixedBuilder & builder )
{
    if ( builder.region != NULL ) { return MixedCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return MixedCookMeasureFrom( ctx, *(const Mixed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool MixedCook( const MixedBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return MixedCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return MixedCookFrom( ctx, *(const Mixed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
// A pointer FIELD is a TableRef — eight bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( __is_trivially_copyable( Placement ), "Placement must stay relocatable" );
static_assert( __is_standard_layout( Placement ), "Placement must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( LogEntry ), "LogEntry must stay relocatable" );
static_assert( __is_standard_layout( LogEntry ), "LogEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Save ), "Save must stay relocatable" );
static_assert( __is_standard_layout( Save ), "Save must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Point ), "Point must stay relocatable" );
static_assert( __is_standard_layout( Point ), "Point must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Mixed ), "Mixed must stay relocatable" );
static_assert( __is_standard_layout( Mixed ), "Mixed must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( Placement ) == 12, "Placement's sizeof moved: the build version was taken over 12, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Placement ) == 4, "Placement's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Placement, x ) == 0, "Placement's field x moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Placement, y ) == 4, "Placement's field y moved: the build version was taken over offset 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Placement, model ) == 8, "Placement's field model moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( LogEntry ) == 4, "LogEntry's sizeof moved: the build version was taken over 4, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( LogEntry ) == 4, "LogEntry's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( LogEntry, tick ) == 0, "LogEntry's field tick moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Save ) == 48, "Save's sizeof moved: the build version was taken over 48, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Save ) == 8, "Save's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Save, placements ) == 0, "Save's field placements moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Save, log ) == 16, "Save's field log moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Save, scores ) == 32, "Save's field scores moved: the build version was taken over offset 32 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Point ) == 8, "Point's sizeof moved: the build version was taken over 8, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Point ) == 4, "Point's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Point, x ) == 0, "Point's field x moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Point, y ) == 4, "Point's field y moved: the build version was taken over offset 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Mixed ) == 64, "Mixed's sizeof moved: the build version was taken over 64, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Mixed ) == 8, "Mixed's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Mixed, grades ) == 0, "Mixed's field grades moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Mixed, perms ) == 16, "Mixed's field perms moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Mixed, hits ) == 32, "Mixed's field hits moved: the build version was taken over offset 32 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Mixed, bounds ) == 48, "Mixed's field bounds moved: the build version was taken over offset 48 (docs/SPEC-TABLES.md §20.3)" );

static_assert( alignof( Placement ) <= kTableAlign, "Save.placements: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( TableRef ) <= kTableAlign, "Save.log: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( int32_t ) <= kTableAlign, "Save.scores: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( Grade ) <= kTableAlign, "Mixed.grades: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( Perm ) <= kTableAlign, "Mixed.perms: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( Hit ) <= kTableAlign, "Mixed.hits: an unbounded array's element alignment must fit the arena's" );
static_assert( alignof( int32_t ) <= kTableAlign, "Mixed.bounds: an unbounded array's element alignment must fit the arena's" );

